begin;
create extension if not exists pgtap with schema extensions;
select plan(4);
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000095','diversity@test.invalid');
insert into public.workspaces(id,name) values ('20000000-0000-4000-8000-000000000095','Diversity');
insert into public.workspace_members values ('20000000-0000-4000-8000-000000000095','10000000-0000-4000-8000-000000000095','owner',now());
create temporary table ids(label text, result jsonb); grant all on ids to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000095","role":"authenticated"}',true);
insert into ids values('a',public.save_case_revision('20000000-0000-4000-8000-000000000095','{"title":"Canary A","template":"product_delivery","outcome":"achieved","problem":"Canary rollout","context":"Canary team","constraints":"Canary limits","approach":"Canary steps","observedOutcome":"Canary released","lessons":"Canary lessons","deliverable":"Canary feature","changeScope":"Canary scope","deploymentConditions":"Canary rollback","sources":[],"conceptIds":[]}'));
insert into ids values('b',public.save_case_revision('20000000-0000-4000-8000-000000000095','{"title":"Canary B","template":"product_delivery","outcome":"not_achieved","problem":"Canary failure","context":"Canary context","constraints":"Canary limits","approach":"Canary skipped","observedOutcome":"Canary failed","lessons":"Canary lessons","deliverable":"Canary feature","changeScope":"Canary scope","deploymentConditions":"Canary rollback","sources":[],"conceptIds":[]}'));
select public.publish_case_revision((select (result->>'revisionId')::uuid from ids where label='a'),(select jsonb_agg(jsonb_build_object('key',key,'text',value,'embedding',to_jsonb(array_prepend(1::float8,array_fill(0::float8,array[1535]))))) from public.case_revisions r,jsonb_each_text(r.content) where r.id=(select (result->>'revisionId')::uuid from ids where label='a') and key in ('problem','context','constraints','approach','observedOutcome','lessons','deliverable','changeScope','deploymentConditions')),'gemini-embedding-2',1536);
select public.publish_case_revision((select (result->>'revisionId')::uuid from ids where label='b'),(select jsonb_agg(jsonb_build_object('key',key,'text',value,'embedding',to_jsonb(array_prepend(1::float8,array_fill(0::float8,array[1535]))))) from public.case_revisions r,jsonb_each_text(r.content) where r.id=(select (result->>'revisionId')::uuid from ids where label='b') and key in ('problem','context','constraints','approach','observedOutcome','lessons','deliverable','changeScope','deploymentConditions')),'gemini-embedding-2',1536);
create temporary table found as select * from public.search_knowledge('20000000-0000-4000-8000-000000000095','canary',array_prepend(1::float8,array_fill(0::float8,array[1535]))::extensions.vector,'method','{}',60,'gemini-embedding-2',2) r(item);
select is((select count(*) from found),4::bigint,'two sections per case are returned');
select is((select max(n) from (select count(*) n from found group by item->>'caseId') x),2::bigint,'no case exceeds the per-case cap');
select is((select count(distinct item->>'caseId') from found),2::bigint,'previews spread across both cases');
select is((select count(*) from public.search_knowledge('20000000-0000-4000-8000-000000000095','canary',array_prepend(1::float8,array_fill(0::float8,array[1535]))::extensions.vector,'method','{}',60,'gemini-embedding-2',9)),18::bigint,'a larger cap returns every matching section');
select * from finish();
rollback;
